const request = $json ?? {};
const headers = request.headers && typeof request.headers === 'object' ? request.headers : {};
const body = request.body && typeof request.body === 'object' ? request.body : request;
const header = (name) => { const key = Object.keys(headers).find((item) => String(item).toLowerCase() === name.toLowerCase()); return key ? headers[key] : undefined; };
const expected = String($env.N8N_WORKFLOWS_TOKEN || '').trim();
const provided = String(header('authorization') || header('x-aiops-workflows-token') || '').replace(/^bearer\s+/i, '').trim();
if (!expected) throw new Error('N8N_WORKFLOWS_TOKEN is not set');
if (provided !== expected) throw new Error('invalid workflows token');
const truthy = (value) => ['1', 'true', 'yes', 'y', 'on'].includes(String(value ?? '').trim().toLowerCase());
return [{ json: { invocation: 'webhook', realm: String(body.realm || $env.N8N_REALM || $env.N8N_ENV_REALM || '').trim(), dry_run: body.dry_run === undefined ? true : truthy(body.dry_run) } }];

const input = $json ?? {};
const realm = String(input.realm || '').trim();
if (!realm) throw new Error('realm is required');
const dryRun = input.dry_run === true;
const cleanBase = (value) => String(value || '').trim().replace(/\/+$/, '');
const keycloakBase = cleanBase($env.N8N_KEYCLOAK_BASE_URL || $env.KEYCLOAK_BASE_URL);
const keycloakAdminRealm = String($env.N8N_KEYCLOAK_ADMIN_REALM || 'master').trim();
const keycloakUser = String($env.N8N_KEYCLOAK_ADMIN_USERNAME || '').trim();
const keycloakPassword = String($env.N8N_KEYCLOAK_ADMIN_PASSWORD || '').trim();
const gitlabBase = cleanBase($env.GITLAB_API_BASE_URL || (($env.GITLAB_BASE_URL || '') + '/api/v4'));
const gitlabToken = String($env.N8N_GITLAB_TOKEN || $env.GITLAB_TOKEN || '').trim();
for (const [name, value] of Object.entries({keycloakBase, keycloakUser, keycloakPassword, gitlabBase, gitlabToken})) { if (!value) throw new Error(`${name} is required`); }
const http = async (method, url, options = {}) => this.helpers.httpRequest({method, url, json: true, timeout: 30000, ...options});
const tokenBody = `client_id=admin-cli&grant_type=password&username=${encodeURIComponent(keycloakUser)}&password=${encodeURIComponent(keycloakPassword)}`;
const tokenResponse = await http('POST', `${keycloakBase}/realms/${encodeURIComponent(keycloakAdminRealm)}/protocol/openid-connect/token`, {headers: {'Content-Type': 'application/x-www-form-urlencoded'}, body: tokenBody});
const accessToken = String(tokenResponse?.access_token || '');
if (!accessToken) throw new Error('Keycloak admin token was not returned');
const kcHeaders = {Authorization: `Bearer ${accessToken}`};
const clients = await http('GET', `${keycloakBase}/admin/realms/${encodeURIComponent(realm)}/clients`, {headers: kcHeaders, qs: {clientId: 'realm-management'}});
const realmManagementId = clients?.[0]?.id;
if (!realmManagementId) throw new Error(`realm-management client was not found for ${realm}`);
const effectiveAdmins = [];
for (let first = 0; ; first += 100) {
  const users = await http('GET', `${keycloakBase}/admin/realms/${encodeURIComponent(realm)}/users`, {headers: kcHeaders, qs: {first, max: 100}});
  for (const user of Array.isArray(users) ? users : []) {
    if (user?.enabled !== true || !String(user?.email || '').trim()) continue;
    const roles = await http('GET', `${keycloakBase}/admin/realms/${encodeURIComponent(realm)}/users/${encodeURIComponent(user.id)}/role-mappings/clients/${encodeURIComponent(realmManagementId)}/composite`, {headers: kcHeaders});
    if ((Array.isArray(roles) ? roles : []).some((role) => role?.name === 'realm-admin')) effectiveAdmins.push({username: String(user.username || ''), email: String(user.email)});
  }
  if (!Array.isArray(users) || users.length < 100) break;
}
const glHeaders = {'PRIVATE-TOKEN': gitlabToken};
const group = await http('GET', `${gitlabBase}/groups/${encodeURIComponent(realm)}`, {headers: glHeaders});
if (!group?.id) throw new Error(`GitLab group was not found: ${realm}`);
const memberIds = new Set();
for (let page = 1; ; page += 1) {
  const members = await http('GET', `${gitlabBase}/groups/${group.id}/members/all`, {headers: glHeaders, qs: {per_page: 100, page}});
  for (const member of Array.isArray(members) ? members : []) memberIds.add(String(member.id));
  if (!Array.isArray(members) || members.length < 100) break;
}
const actions = [];
const waitingForGitLab = [];
for (const admin of effectiveAdmins) {
  const users = await http('GET', `${gitlabBase}/users`, {headers: glHeaders, qs: {search: admin.username || admin.email, per_page: 100}});
  const gitlabUser = (Array.isArray(users) ? users : []).find((user) => String(user.username || '').toLowerCase() === admin.username.toLowerCase() || String(user.email || user.public_email || '').toLowerCase() === admin.email.toLowerCase() || (Array.isArray(user.identities) && user.identities.some((identity) => identity?.provider === 'openid_connect' && identity?.extern_uid === admin.username)));
  if (!gitlabUser) { waitingForGitLab.push({...admin, reason: 'gitlab_user_not_created'}); continue; }
  if (memberIds.has(String(gitlabUser.id))) continue;
  actions.push({action: 'add_owner', user_id: gitlabUser.id, username: gitlabUser.username, email: admin.email, group_id: group.id});
  if (!dryRun) await http('POST', `${gitlabBase}/groups/${group.id}/members`, {headers: glHeaders, body: {user_id: gitlabUser.id, access_level: 50}});
}
return [{json: {ok: true, workflow_id: 'wf.gitlab_realm_admin_membership_sync', invocation: input.invocation, realm, dry_run: dryRun, effective_admins: effectiveAdmins, actions, waiting_for_gitlab: waitingForGitLab, applied: dryRun ? 0 : actions.length, checked_at: new Date().toISOString()}}];
